query get($id: bigint!) {
  products_by_pk(id: $id) {
    id
    title
    label
    internal_tags
    fulfillment_id
    fulfillment_linked_id
    fulfillment {
      display_name
      name
      __typename
    }
    description
    default_options
    thumbnail
    is_imported
    design_format
    created_at
    campaign_products {
      created_at
      campaign {
        id
        name
        campaign_instances {
          id
          need_sync
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query get($id: bigint!) {
  printareas(
    order_by: [{position: asc}, {id: asc}]
    where: {product_id: {_eq: $id}}
  ) {
    id
    name
    display_name
    width
    height
    position
    product_id
    __typename
  }
}

query get {
  products_by_pk(id: 3243) {
    id
    campaign_products {
      id
      campaign {
        id
        status
        campaign_instances(where: {instance: {deleted_at: {_is_null: true}}}) {
          id
          need_sync
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

